theorem Lean.Grind.AC.Seq.insert.eq_def (x : Lean.Grind.AC.Var) (s : Lean.Grind.AC.Seq) :
  Lean.Grind.AC.Seq.insert x s =
    match s with
    | Lean.Grind.AC.Seq.var y =>
      if Nat.blt x y = true then Lean.Grind.AC.Seq.cons x (Lean.Grind.AC.Seq.var y)
      else Lean.Grind.AC.Seq.cons y (Lean.Grind.AC.Seq.var x)
    | Lean.Grind.AC.Seq.cons y s =>
      if Nat.blt x y = true then Lean.Grind.AC.Seq.cons x (Lean.Grind.AC.Seq.cons y s)
      else Lean.Grind.AC.Seq.cons y (Lean.Grind.AC.Seq.insert x s)

